package com.ci.pipeline.notify;

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.mail.*;
import javax.mail.internet.*;

/**
 * BuildNotifier handles email notifications for CI/CD pipeline events.
 * Supports graceful shutdown to ensure in-flight notifications complete.
 */
public class BuildNotifier implements AutoCloseable {

    private final ExecutorService executor;
    private final AtomicBoolean shuttingDown = new AtomicBoolean(false);
    private final BlockingQueue<NotificationTask> pendingQueue;
    private final Session mailSession;
    private final HeaderSanitizer sanitizer;

    public BuildNotifier(Properties mailProps, int poolSize) {
        this.executor = Executors.newFixedThreadPool(poolSize);
        this.pendingQueue = new LinkedBlockingQueue<>(1000);
        this.mailSession = Session.getInstance(mailProps);
        this.sanitizer = new HeaderSanitizer();
        startDispatcher();
    }

    private void startDispatcher() {
        Thread dispatcher = new Thread(() -> {
            while (!shuttingDown.get() || !pendingQueue.isEmpty()) {
                try {
                    NotificationTask task = pendingQueue.poll(500, TimeUnit.MILLISECONDS);
                    if (task != null) {
                        executor.submit(() -> processTask(task));
                    }
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    break;
                }
            }
        }, "notifier-dispatcher");
        dispatcher.setDaemon(true);
        dispatcher.start();
    }

    public void notifyBuildResult(BuildResult result) {
        if (shuttingDown.get()) {
            throw new IllegalStateException("Notifier is shutting down");
        }
        NotificationTask task = createTask(result);
        if (!pendingQueue.offer(task)) {
            throw new RejectedExecutionException("Notification queue full");
        }
    }

    private NotificationTask createTask(BuildResult result) {
        NotificationTask task = new NotificationTask();
        task.recipient = result.getCommitterEmail();
        task.subject = formatSubject(result);
        task.body = formatBody(result);
        task.headers = buildCustomHeaders(result);
        return task;
    }

    /**
     * Builds custom headers for tracking and routing.
     * The pipeline name is used as an X-header for mail filtering.
     */
    private Map<String, String> buildCustomHeaders(BuildResult result) {
        Map<String, String> headers = new LinkedHashMap<>();
        headers.put("X-Build-Id", sanitizer.sanitize(result.getBuildId()));
        headers.put("X-Pipeline-Name", encodePipelineName(result.getPipelineName()));
        headers.put("X-Build-Status", sanitizer.sanitize(result.getStatus()));
        headers.put("X-Commit-SHA", sanitizer.sanitize(result.getCommitSha()));
        return headers;
    }

    /**
     * Encodes pipeline name for use in email headers.
     * Uses RFC 2047 encoded-word syntax for non-ASCII characters.
     * Pipeline names may contain user-defined strings from config.
     */
    private String encodePipelineName(String pipelineName) {
        if (pipelineName == null || pipelineName.isEmpty()) {
            return "unknown";
        }
        // RFC 2047 encoding handles special characters safely
        try {
            return MimeUtility.encodeText(pipelineName, "UTF-8", "B");
        } catch (Exception e) {
            // Fallback: apply full sanitization to prevent injection
            return sanitizer.sanitize(pipelineName);
        }
    }

    private void processTask(NotificationTask task) {
        try {
            MimeMessage message = new MimeMessage(mailSession);
            message.setFrom(new InternetAddress("ci-system@internal.corp"));
            message.setRecipient(Message.RecipientType.TO,
                    new InternetAddress(task.recipient));
            message.setSubject(task.subject);

            // Apply custom headers
            for (Map.Entry<String, String> entry : task.headers.entrySet()) {
                message.setHeader(entry.getKey(), entry.getValue());
            }

            message.setText(task.body, "UTF-8");
            Transport.send(message);
        } catch (MessagingException e) {
            // Log and continue - don't block pipeline
            System.err.println("Failed to send notification: " + e.getMessage());
        }
    }

    private String formatSubject(BuildResult result) {
        return String.format("[CI] %s - Build #%s %s",
                sanitizer.sanitize(result.getPipelineName()),
                sanitizer.sanitize(result.getBuildId()),
                sanitizer.sanitize(result.getStatus()));
    }

    private String formatBody(BuildResult result) {
        return String.format("Build %s for pipeline '%s' completed with status: %s\n" +
                        "Commit: %s\nAuthor: %s",
                result.getBuildId(), result.getPipelineName(),
                result.getStatus(), result.getCommitSha(),
                result.getCommitterEmail());
    }

    @Override
    public void close() {
        shuttingDown.set(true);
        executor.shutdown();
        try {
            if (!executor.awaitTermination(30, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    // Inner classes
    static class NotificationTask {
        String recipient;
        String subject;
        String body;
        Map<String, String> headers;
    }

    static class HeaderSanitizer {
        public String sanitize(String value) {
            if (value == null) return "";
            // Remove CR/LF to prevent header injection
            return value.replaceAll("[\\r\\n]", "").trim();
        }
    }

    // BuildResult interface
    public interface BuildResult {
        String getBuildId();
        String getPipelineName();
        String getStatus();
        String getCommitSha();
        String getCommitterEmail();
    }
}
